sealed class TarotException: kotlin.Exception() {
    
    class InvalidSeed(
        
        val v1: kotlin.String
        ) : TarotException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class CardIndexOutOfBounds(
        
        val v1: kotlin.UByte
        ) : TarotException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class DuplicateCardDraw(
        
        val v1: kotlin.UByte
        ) : TarotException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class SpreadSlotOverflow(
        
        val `requested`: kotlin.ULong, 
        
        val `capacity`: kotlin.ULong
        ) : TarotException() {
        override val message
            get() = "requested=${ `requested` }, capacity=${ `capacity` }"
    }
    
    class ConstraintViolation(
        
        val `slotId`: kotlin.UByte, 
        
        val `required`: kotlin.String, 
        
        val `actual`: kotlin.String
        ) : TarotException() {
        override val message
            get() = "slotId=${ `slotId` }, required=${ `required` }, actual=${ `actual` }"
    }
    
    class SpreadNotFound(
        
        val v1: kotlin.String
        ) : TarotException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class DeserializationException(
        
        val v1: kotlin.String
        ) : TarotException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class AiProviderUnavailable(
        
        val v1: kotlin.String
        ) : TarotException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Unauthorized(
        
        val v1: kotlin.String
        ) : TarotException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<TarotException> {
        override fun lift(error_buf: RustBuffer.ByValue): TarotException = FfiConverterTypeTarotError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeTarotError : FfiConverterRustBuffer<TarotException> {
    override fun read(buf: ByteBuffer): TarotException {
        

        return when(buf.getInt()) {
            1 -> TarotException.InvalidSeed(
                FfiConverterString.read(buf),
                )
            2 -> TarotException.CardIndexOutOfBounds(
                FfiConverterUByte.read(buf),
                )
            3 -> TarotException.DuplicateCardDraw(
                FfiConverterUByte.read(buf),
                )
            4 -> TarotException.SpreadSlotOverflow(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            5 -> TarotException.ConstraintViolation(
                FfiConverterUByte.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            6 -> TarotException.SpreadNotFound(
                FfiConverterString.read(buf),
                )
            7 -> TarotException.DeserializationException(
                FfiConverterString.read(buf),
                )
            8 -> TarotException.AiProviderUnavailable(
                FfiConverterString.read(buf),
                )
            9 -> TarotException.Unauthorized(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: TarotException): ULong {
        return when(value) {
            is TarotException.InvalidSeed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is TarotException.CardIndexOutOfBounds -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUByte.allocationSize(value.v1)
            )
            is TarotException.DuplicateCardDraw -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUByte.allocationSize(value.v1)
            )
            is TarotException.SpreadSlotOverflow -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`requested`)
                + FfiConverterULong.allocationSize(value.`capacity`)
            )
            is TarotException.ConstraintViolation -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUByte.allocationSize(value.`slotId`)
                + FfiConverterString.allocationSize(value.`required`)
                + FfiConverterString.allocationSize(value.`actual`)
            )
            is TarotException.SpreadNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is TarotException.DeserializationException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is TarotException.AiProviderUnavailable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is TarotException.Unauthorized -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: TarotException, buf: ByteBuffer) {
        when(value) {
            is TarotException.InvalidSeed -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is TarotException.CardIndexOutOfBounds -> {
                buf.putInt(2)
                FfiConverterUByte.write(value.v1, buf)
                Unit
            }
            is TarotException.DuplicateCardDraw -> {
                buf.putInt(3)
                FfiConverterUByte.write(value.v1, buf)
                Unit
            }
            is TarotException.SpreadSlotOverflow -> {
                buf.putInt(4)
                FfiConverterULong.write(value.`requested`, buf)
                FfiConverterULong.write(value.`capacity`, buf)
                Unit
            }
            is TarotException.ConstraintViolation -> {
                buf.putInt(5)
                FfiConverterUByte.write(value.`slotId`, buf)
                FfiConverterString.write(value.`required`, buf)
                FfiConverterString.write(value.`actual`, buf)
                Unit
            }
            is TarotException.SpreadNotFound -> {
                buf.putInt(6)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is TarotException.DeserializationException -> {
                buf.putInt(7)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is TarotException.AiProviderUnavailable -> {
                buf.putInt(8)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is TarotException.Unauthorized -> {
                buf.putInt(9)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




